func applyAuthHeader(request *http.Request, cfg config.UpstageConfig) {
	if cfg.AuthToken == "" {
		return
	}
	if cfg.AuthMode == "x-api-key" {
		request.Header.Set("x-api-key", cfg.AuthToken)
		return
	}
	request.Header.Set("Authorization", "Bearer "+cfg.AuthToken)
}

func (c *Client) httpClient() *http.Client {
	timeout := c.config.Timeout
	if timeout <= 0 {
		timeout = 30 * time.Second
	}
	return &http.Client{
		Timeout: timeout,
		CheckRedirect: func(request *http.Request, via []*http.Request) error {
			if len(via) >= maxUpstreamRedirects {
				return fmt.Errorf("stopped after %d redirects", maxUpstreamRedirects)
			}
			if len(via) > 0 {
				if err := checkRedirectScheme(via[0].URL, request.URL); err != nil {
					return err
				}
			}
			return c.checkURLAllowed(request.URL)
		},
	}
}

// checkRedirectScheme refuses a redirect that drops a request that started on
// https down to plain http. Go replays the multipart body from GetBody on 307 and
// 308, so following such a redirect would put the uploaded document and the API
// token back on the wire in clear text. A chain that started on http (the
// embedded mock upstream, or an operator who configured a plain endpoint on
// purpose) is left alone.
func checkRedirectScheme(first *url.URL, target *url.URL) error {
	if first == nil || target == nil {
		return nil
	}
	if !strings.EqualFold(first.Scheme, "https") {
		return nil
	}
	if strings.EqualFold(target.Scheme, "https") {
		return nil
	}
	return fmt.Errorf("refusing to follow a redirect from https to %s", defaultIfEmpty(target.Scheme, "an empty scheme"))
}

// allowedHosts lists the hosts this client may talk to. An empty configuration
// falls back to the host of the configured base URL, so the client can never be
// left without a target restriction.
func (c *Client) allowedHosts() []string {
	if len(c.config.AllowHosts) > 0 {
		return c.config.AllowHosts
	}
	parsedURL, err := url.Parse(c.config.BaseURL)
	if err != nil {
		return nil
	}
	if host := parsedURL.Hostname(); host != "" {
		return []string{host}
	}
	return nil
}

// checkHostAllowed rejects a target URL before any request body is built.
func (c *Client) checkHostAllowed(rawURL string) error {
	parsedURL, err := url.Parse(rawURL)
	if err != nil {
		return &blockedHostError{host: rawURL}
	}
	return c.checkURLAllowed(parsedURL)
}

func (c *Client) checkURLAllowed(target *url.URL) error {
	if hostAllowed(target, c.allowedHosts()) {
		return nil
	}
	return &blockedHostError{host: target.Host}
}

// hostAllowed matches target against the allow list entries, which may be written
// either as a bare host name or with an explicit port.
func hostAllowed(target *url.URL, allowed []string) bool {
	if target == nil {
		return false
	}
	hostname := strings.ToLower(target.Hostname())
	hostPort := strings.ToLower(target.Host)
	if hostname == "" {
		return false
	}
	for _, entry := range allowed {
		entry = strings.ToLower(strings.TrimSpace(entry))
		if entry == "" {
			continue
		}
		if entry == hostname || entry == hostPort {
			return true
		}
	}
	return false
}

func cloneFields(fields map[string]string) map[string]string {
	copied := make(map[string]string, len(fields))
	for key, value := range fields {
		copied[key] = value
	}
	return copied
}

