func (s *Server) handleGetJob(w http.ResponseWriter, r *http.Request) {
	jobID := mux.Vars(r)["job_id"]
	job, ok, err := s.service.GetJob(jobID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, &core.APIError{
			Code:    "job_lookup_failed",
			Message: err.Error(),
		})
		return
	}
	if !ok {
		writeError(w, http.StatusNotFound, &core.APIError{
			Code:    "job_not_found",
			Message: "작업을 찾을 수 없습니다.",
		})
		return
	}
	if job.Metadata.Status == "completed" && job.OutputPath != "" {
		job.Metadata.Output.DownloadURL = service.JoinPublicURL(s.config.Server.PublicBaseURL, "v1", "jobs", job.ID, "result")
	} else {
		job.Metadata.Output.DownloadURL = ""
	}
	writeJSON(w, http.StatusOK, job.Metadata)
}

func (s *Server) handleGetJobResult(w http.ResponseWriter, r *http.Request) {
	jobID := mux.Vars(r)["job_id"]
	job, ok, err := s.service.GetJob(jobID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, &core.APIError{
			Code:    "job_lookup_failed",
			Message: err.Error(),
		})
		return
	}
	if !ok || job.Metadata.Status != "completed" || job.OutputPath == "" {
		writeError(w, http.StatusNotFound, &core.APIError{
			Code:    "job_result_not_found",
			Message: "결과 파일을 찾을 수 없습니다.",
		})
		return
	}

	// The result is streamed straight off disk instead of being buffered, so a burst
	// of downloads cannot pin one masked file per request in memory.
	file, err := os.Open(job.OutputPath)
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			writeError(w, http.StatusNotFound, &core.APIError{
				Code:    "job_result_not_found",
				Message: "결과 파일을 찾을 수 없습니다.",
			})
			return
		}
		writeError(w, http.StatusInternalServerError, &core.APIError{
			Code:    "result_read_failed",
			Message: err.Error(),
		})
		return
	}
	defer file.Close()

	info, err := file.Stat()
	if err != nil {
		writeError(w, http.StatusInternalServerError, &core.APIError{
			Code:    "result_read_failed",
			Message: err.Error(),
		})
		return
	}

	if mimeType := job.Metadata.Output.MIMEType; mimeType != "" {
		w.Header().Set("Content-Type", mimeType)
	}
	w.Header().Set("Content-Disposition", attachmentDisposition(job.Metadata.Output.FileName))
	http.ServeContent(w, r, job.Metadata.Output.FileName, info.ModTime(), file)
}

func (s *Server) handleHistory(w http.ResponseWriter, r *http.Request) {
	items, err := s.service.ListJobs(historyLimit(r.URL.Query().Get("limit")))
	if err != nil {
		writeError(w, http.StatusInternalServerError, &core.APIError{
			Code:    "history_lookup_failed",
			Message: err.Error(),
		})
		return
	}

	response := make([]core.ProcessMetadata, 0, len(items))
	for _, item := range items {
		if item.Metadata.Status == "completed" && item.OutputPath != "" {
			item.Metadata.Output.DownloadURL = service.JoinPublicURL(s.config.Server.PublicBaseURL, "v1", "jobs", item.ID, "result")
		} else {
			item.Metadata.Output.DownloadURL = ""
		}
		response = append(response, item.Metadata)
	}
	writeJSON(w, http.StatusOK, map[string]any{"items": response})
}

