func (s *Store) load() error {
	s.mu.Lock()
	defer s.mu.Unlock()

	entries, err := os.ReadDir(s.root)
	if err != nil {
		return fmt.Errorf("failed to read jobs dir: %w", err)
	}
	for _, entry := range entries {
		if !entry.IsDir() {
			continue
		}
		jobDir := filepath.Join(s.root, entry.Name())
		job, ok := readJobRecord(jobDir, entry.Name())
		if !ok {
			if err := os.RemoveAll(jobDir); err != nil {
				log.Printf("failed to remove orphaned job directory %s: %v", jobDir, err)
			} else {
				log.Printf("removed orphaned job directory %s", jobDir)
			}
			continue
		}
		job.InputPath = firstExistingFile(jobDir, "input_")
		// A leftover output is not proof that writing and completion succeeded.
		if job.Metadata.Status == "completed" {
			job.OutputPath = firstExistingFile(jobDir, "output_")
		} else {
			job.Metadata.Output.DownloadURL = ""
		}
		interrupted := job.Metadata.Status == "queued" || job.Metadata.Status == "running"
		if interrupted {
			job.Metadata.Status = "failed"
			job.Metadata.Error = &core.APIError{
				Code:      "job_interrupted",
				Message:   "서버 재기동으로 작업이 중단되었습니다.",
				Retryable: true,
			}
		}
		s.jobs[job.ID] = cloneJob(job)
		if interrupted {
			// Best effort: a directory that cannot be written only means the next
			// start repeats the same transition, which changes nothing.
			_ = s.persistLocked(job.ID)
		}
	}
	return nil
}

// readJobRecord decodes the record stored in a job directory. It reports false
// when there is no usable record: the file is missing or not valid JSON, or the
// id inside does not match the directory, which every write path derives from the
// id and which the retention sweep therefore would never remove.
func readJobRecord(jobDir, expectedID string) (*core.JobRecord, bool) {
// that is safe to embed in a multipart part header and to write to disk. Clients
// may send the name RFC 2231 encoded, so the decoded value can carry CR/LF or
// quotes that would otherwise break out of a Content-Disposition header.
func sanitizeUploadFilename(name string) string {
	name = strings.TrimSpace(name)
	if name == "" {
		return "document"
	}
	base := filepath.Base(name)
	if index := strings.LastIndexAny(base, `/\`); index >= 0 {
		base = base[index+1:]
	}
	base = strings.TrimSpace(stripUnsafeFilenameRunes(base))
	if base == "" || strings.Trim(base, ".") == "" {
		return "document"
	}
	return truncateFilename(base, maxUploadFilenameBytes)
}

// stripUnsafeFilenameRunes drops the characters that would let a file name escape
// the header field or the directory it is written to.
func stripUnsafeFilenameRunes(name string) string {
	var builder strings.Builder
	builder.Grow(len(name))
	for _, r := range name {
		switch {
		case r == utf8.RuneError, unicode.IsControl(r):
			continue
		case r == '"', r == '\\', r == '/':
			continue
		default:
			builder.WriteRune(r)
		}
	}
	return builder.String()
}

// truncateFilename shortens a name to maxBytes while keeping its extension and
// never cutting a multi byte rune in half.
func truncateFilename(name string, maxBytes int) string {
	if len(name) <= maxBytes {
		return name
	}
	extension := filepath.Ext(name)
	if len(extension) > 16 || len(extension) >= maxBytes {
		extension = ""
	}
	stem := name[:len(name)-len(extension)]
	limit := maxBytes - len(extension)
	truncated := make([]byte, 0, limit)
	for _, r := range stem {
		if len(truncated)+utf8.RuneLen(r) > limit {
			break
		}
		truncated = utf8.AppendRune(truncated, r)
	}
	if len(truncated) == 0 {
		return "document" + extension
	}
	return string(truncated) + extension
}

